BEGIN;
CREATE TABLE IF NOT EXISTS investment.subscription_account(account_id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES customer.profile(customer_id),product_id uuid NOT NULL REFERENCES product.investment_product(product_id),product_terms_version_id uuid NOT NULL REFERENCES product.terms_version(terms_version_id),contract_version text NOT NULL,investor_nisba numeric(9,6) NOT NULL,bank_nisba numeric(9,6) NOT NULL,currency_code text NOT NULL,status text NOT NULL CHECK(status IN('PRE_SIMULATION','PENDING_SUBSCRIPTION','ACTIVE','BLOCKED','MATURED','SUCCESSION','CLOSED')),opened_on date,maturity_date date,closed_on date,accepted_at timestamptz,accepted_by text,non_guarantee_accepted boolean NOT NULL DEFAULT false,profit_sharing_method_accepted boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(investor_nisba+bank_nisba=100),CHECK(status NOT IN('ACTIVE','BLOCKED','MATURED','SUCCESSION','CLOSED') OR(non_guarantee_accepted AND profit_sharing_method_accepted AND accepted_at IS NOT NULL)),CHECK(status<>'CLOSED' OR closed_on IS NOT NULL));
CREATE TABLE IF NOT EXISTS investment.subscription_event(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES investment.subscription_account(account_id),event_type text NOT NULL,business_date date NOT NULL,actor_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',idempotency_key text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_id,idempotency_key));
CREATE OR REPLACE FUNCTION investment.reject_subscription_event_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Investment subscription history is append-only';END;$$;DROP TRIGGER IF EXISTS subscription_event_immutable ON investment.subscription_event;CREATE TRIGGER subscription_event_immutable BEFORE UPDATE OR DELETE ON investment.subscription_event FOR EACH ROW EXECUTE FUNCTION investment.reject_subscription_event_mutation();
COMMIT;
